  function cloudRefreshAppointments(){var local=validCloudAppointments();fetch('/api/no11-appointments?ts='+Date.now(),{cache:'no-store'}).then(function(r){if(!r.ok)throw new Error('load');return r.json()}).then(function(data){if(!Array.isArray(data.appointments))return;if(!data.appointments.length&&local.length){return cloudSaveAppointments()}state.items=data.appointments.map(function(x){return Object.assign({status:'pending',managerNote:'',studentNote:'',phone:''},x,{service:x.service||'Pilates'})});state.selected=state.items[0]||null;save(K.appointments,state.items);if(state.page==='dashboard'||state.page==='program'||state.page==='appointments')render()}).catch(function(){})}
