  function turkeyNow(){var parts={};new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',hourCycle:'h23'}).formatToParts(new Date()).forEach(function(part){if(part.type!=='literal')parts[part.type]=part.value});return {key:parts.year+'-'+parts.month+'-'+parts.day,hour:Number(parts.hour)||0}}
